namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

public class Instructor
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Bio { get; set; } = string.Empty;
    public string Email { get; set; } = string.Empty;
}

public class Course
{
    public int Id { get; set; }
    public string Code { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public int DepartmentId { get; set; }
    public Department Department { get; set; } = null!;
    public Instructor Instructor { get; set; } = null!;
    public bool IsFeatured { get; set; }
}

public class EnrollmentRequest
{
    public string StudentName { get; set; } = string.Empty;
    public string StudentId { get; set; } = string.Empty;
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Instructor> _instructors;
    private readonly List<Course> _courses;
    private readonly List<EnrollmentRequest> _enrollments = new();

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Study of numbers, quantity, structure, and space." },
            new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 4, Name = "English", Code = "ENG", Description = "Study of literature, writing, and language." },
            new() { Id = 5, Name = "History", Code = "HIST", Description = "Study of past events and human civilization." }
        };

        _instructors = new List<Instructor>
        {
            new() { Id = 1, Name = "Dr. Sarah Chen", Title = "Professor of Computer Science", Bio = "Dr. Chen specializes in artificial intelligence and machine learning. She has published over 50 papers and holds 3 patents in neural network architectures.", Email = "s.chen@university.edu" },
            new() { Id = 2, Name = "Dr. James Wilson", Title = "Associate Professor of Computer Science", Bio = "Dr. Wilson focuses on distributed systems and cloud computing. He previously worked at a major tech company for 10 years before joining academia.", Email = "j.wilson@university.edu" },
            new() { Id = 3, Name = "Dr. Maria Garcia", Title = "Professor of Mathematics", Bio = "Dr. Garcia is an expert in abstract algebra and number theory. She received the Distinguished Teaching Award three years in a row.", Email = "m.garcia@university.edu" },
            new() { Id = 4, Name = "Dr. Robert Taylor", Title = "Associate Professor of Physics", Bio = "Dr. Taylor researches quantum mechanics and particle physics. He was part of the team that confirmed the Higgs boson discovery.", Email = "r.taylor@university.edu" },
            new() { Id = 5, Name = "Dr. Emily Brooks", Title = "Professor of English", Bio = "Dr. Brooks specializes in modern American literature and creative writing. She is an award-winning novelist and poet.", Email = "e.brooks@university.edu" },
            new() { Id = 6, Name = "Dr. David Park", Title = "Professor of History", Bio = "Dr. Park studies modern world history with a focus on diplomatic relations. He has authored several bestselling history books.", Email = "d.park@university.edu" }
        };

        _courses = new List<Course>
        {
            new() { Id = 1, Code = "CS 101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Topics include variables, control structures, functions, and basic data structures. No prior experience required.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", DepartmentId = 1, Department = _departments[0], Instructor = _instructors[0], IsFeatured = true },
            new() { Id = 2, Code = "CS 201", Title = "Data Structures & Algorithms", Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs) and algorithm design techniques (sorting, searching, dynamic programming).", Credits = 4, Schedule = "Tue/Thu 10:00–11:50 AM", DepartmentId = 1, Department = _departments[0], Instructor = _instructors[0], IsFeatured = true },
            new() { Id = 3, Code = "CS 301", Title = "Distributed Systems", Description = "Principles of distributed computing including consensus algorithms, replication, fault tolerance, and modern cloud architectures.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", DepartmentId = 1, Department = _departments[0], Instructor = _instructors[1], IsFeatured = false },
            new() { Id = 4, Code = "CS 350", Title = "Machine Learning", Description = "Introduction to machine learning concepts including supervised learning, unsupervised learning, neural networks, and practical applications.", Credits = 4, Schedule = "Tue/Thu 1:00–2:50 PM", DepartmentId = 1, Department = _departments[0], Instructor = _instructors[0], IsFeatured = true },
            new() { Id = 5, Code = "MATH 101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering problems.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", DepartmentId = 2, Department = _departments[1], Instructor = _instructors[2], IsFeatured = false },
            new() { Id = 6, Code = "MATH 201", Title = "Linear Algebra", Description = "Vector spaces, matrices, linear transformations, eigenvalues, and applications to computer science and engineering.", Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", DepartmentId = 2, Department = _departments[1], Instructor = _instructors[2], IsFeatured = true },
            new() { Id = 7, Code = "MATH 301", Title = "Abstract Algebra", Description = "Groups, rings, fields, and their applications. Emphasis on proof techniques and mathematical reasoning.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", DepartmentId = 2, Department = _departments[1], Instructor = _instructors[2], IsFeatured = false },
            new() { Id = 8, Code = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes weekly laboratory sessions with hands-on experiments.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM + Lab Thu 2:00–4:50 PM", DepartmentId = 3, Department = _departments[2], Instructor = _instructors[3], IsFeatured = false },
            new() { Id = 9, Code = "PHYS 301", Title = "Quantum Mechanics", Description = "Introduction to quantum theory: wave functions, Schrödinger equation, angular momentum, and spin. Prerequisites: PHYS 201, MATH 201.", Credits = 4, Schedule = "Tue/Thu 10:00–11:50 AM", DepartmentId = 3, Department = _departments[2], Instructor = _instructors[3], IsFeatured = true },
            new() { Id = 10, Code = "ENG 101", Title = "College Writing", Description = "Develop critical thinking and writing skills through reading, analysis, and composition of various essay forms.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", DepartmentId = 4, Department = _departments[3], Instructor = _instructors[4], IsFeatured = false },
            new() { Id = 11, Code = "ENG 250", Title = "Modern American Literature", Description = "Survey of American literature from 1900 to present. Authors include Fitzgerald, Hemingway, Morrison, and DeLillo.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", DepartmentId = 4, Department = _departments[3], Instructor = _instructors[4], IsFeatured = false },
            new() { Id = 12, Code = "HIST 101", Title = "World History to 1500", Description = "Survey of world civilizations from prehistory through the Renaissance, examining political, social, and cultural developments.", Credits = 3, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", DepartmentId = 5, Department = _departments[4], Instructor = _instructors[5], IsFeatured = false },
            new() { Id = 13, Code = "HIST 250", Title = "Modern World History", Description = "Examination of global events from the Enlightenment through the present day, including revolutions, world wars, and globalization.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", DepartmentId = 5, Department = _departments[4], Instructor = _instructors[5], IsFeatured = true }
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses() => _courses;

    public List<Course> SearchCourses(string? searchTerm, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Instructor.Name.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public void SubmitEnrollment(EnrollmentRequest request)
    {
        _enrollments.Add(request);
    }
}

